import {chromium} from 'playwright';import fs from 'node:fs';
const mode=process.argv[2],origin='https://thesheemaedit.com';fs.mkdirSync('.github/reports',{recursive:true});fs.mkdirSync('assets/mobile-previews',{recursive:true});const browser=await chromium.launch();const results=[],failures=[];
const routes=[['home','/'],['edit','/posts/im-allowed-to-be-happy-before-im-okay.html'],['about','/about.html'],['shop','/shop/'],['journal','/shop/reflection-journal-product.html'],['planner','/shop/gentle-weekly-planner.html'],['bundle','/shop/reset-bundle.html'],['thanks','/thank-you/'],['offline','/offline.html'],['404','/404.html']];
if(mode==='after')for(let i=0;i<48;i++){const s=await(await fetch(origin+'assets/css/home-editorial.css?check='+Date.now())).text();if(s.includes('Mobile cover notes'))break;if(i===47)throw Error('Deployment pending');await new Promise(r=>setTimeout(r,10000))}
for(const width of mode==='before'?[1280,1440]:[360,375,390,430,1280,1440]){const ctx=await browser.newContext({viewport:{width,height:844},serviceWorkers:'block',deviceScaleFactor:1});const page=await ctx.newPage();
for(const[name,path]of routes){await page.goto(origin+path+'?mobile='+Date.now(),{waitUntil:'networkidle'});await page.evaluate(()=>document.fonts.ready);const state=await page.evaluate(()=>({overflow:document.documentElement.scrollWidth>innerWidth+1,body:document.body.innerText,title:document.querySelector('h1')?.innerText,hero:document.querySelector('.editorial-feature-copy .button')?.getBoundingClientRect().bottom}));
if(state.overflow)failures.push(`${name} ${width} overflow`);
if(name==='home'&&width<721&&state.hero>844)failures.push(`Reading button below first screen ${width}: ${state.hero}`);
if(width>=721){const buf=await page.screenshot({fullPage:true});const file=`.github/reports/baseline-${name}-${width}.png`;if(mode==='before')fs.writeFileSync(file,buf);else if(!buf.equals(fs.readFileSync(file)))failures.push(`${name} ${width}: desktop screenshot changed`);}
if(mode==='after'&&width<721){await page.screenshot({path:`assets/mobile-previews/${name}-${width}.png`,fullPage:true});if(name==='home'){await page.screenshot({path:`assets/mobile-previews/first-screen-${width}.png`});for(const key of ['mind','motherhood','chronic','lifestyle','all']){await page.locator(`[data-filter="${key}"]`).click();if(await page.locator(`[data-filter="${key}"]`).getAttribute('aria-pressed')!=='true')failures.push(`Filter ${key} ${width}`)}await page.locator('.menu-toggle').click();if(!await page.locator('.site-nav').isVisible())failures.push(`Menu ${width}`);await page.keyboard.press('Escape');if(await page.locator('.site-nav').isVisible())failures.push(`Menu Escape ${width}`)}}
results.push({name,width,overflow:state.overflow,readingButtonBottom:state.hero});}
await ctx.close()}
await browser.close();fs.writeFileSync(`.github/reports/mobile-${mode}.json`,JSON.stringify({results,failures},null,2));console.log({checks:results.length,failures});if(failures.length)process.exitCode=1;
